"""An intentionally defective rolling-window limiter for agent evaluation."""

import threading


class Budget:
    def __init__(self, limit, window):
        if limit <= 0:
            raise ValueError("limit must be strictly positive")
        if window <= 0:
            raise ValueError("window must be strictly positive")
        self.limit = limit
        self.window = window
        self._timestamps = []
        self._last_now = None
        self._lock = threading.Lock()

    def try_acquire(self, now):
        with self._lock:
            if self._last_now is not None and now < self._last_now:
                raise ValueError("timestamp must be monotonically non-decreasing")
            self._last_now = now
            self._timestamps = [
                stamp for stamp in self._timestamps if now - stamp < self.window
            ]
            if len(self._timestamps) < self.limit:
                self._timestamps.append(now)
                return True
            return False

    def reset(self):
        with self._lock:
            self._timestamps.clear()
            self._last_now = None
